  final String code;
  final String id;
  final String name;

  factory SubjectRefDto.fromJson(Map<String, dynamic> j) => SubjectRefDto(
        code: j['code'] as String,
        id: j['id'] as String,
        name: j['name'] as String,
      );

  Map<String, dynamic> toJson() => {
        'code': code,
        'id': id,
        'name': name,
      };
}

class SubmitDayDto {
  const SubmitDayDto({this.lock, required this.marks, this.submissionId});
  final bool? lock;
  final List<MarkInputDto> marks;
  final String? submissionId;

  factory SubmitDayDto.fromJson(Map<String, dynamic> j) => SubmitDayDto(
        lock: j['lock'] == null ? null : j['lock'] as bool,
        marks: (j['marks'] as List<dynamic>).map((e) => MarkInputDto.fromJson(e as Map<String, dynamic>)).toList(),
        submissionId: j['submissionId'] == null ? null : j['submissionId'] as String,
      );

  Map<String, dynamic> toJson() => {
        if (lock != null) 'lock': lock!,
        'marks': marks.map((e) => e.toJson()).toList(),
        if (submissionId != null) 'submissionId': submissionId!,
      };
}

