class TombstoneDto {
  const TombstoneDto({required this.classId, required this.deletedAt, required this.entityId, required this.entityType, required this.id, required this.staffId});
  final String? classId;
  final String deletedAt;
  final String entityId;
  final String entityType;
  final String id;
  final String? staffId;

  factory TombstoneDto.fromJson(Map<String, dynamic> j) => TombstoneDto(
        classId: j['classId'] == null ? null : j['classId'] as String,
        deletedAt: j['deletedAt'] as String,
        entityId: j['entityId'] as String,
        entityType: j['entityType'] as String,
        id: j['id'] as String,
        staffId: j['staffId'] == null ? null : j['staffId'] as String,
      );

  Map<String, dynamic> toJson() => {
        if (classId != null) 'classId': classId!,
        'deletedAt': deletedAt,
        'entityId': entityId,
        'entityType': entityType,
        'id': id,
        if (staffId != null) 'staffId': staffId!,
      };
}

class TombstoneListDto {
  const TombstoneListDto({required this.items, required this.more, required this.next});
  final List<TombstoneDto> items;
  final bool more;
  final String next;

  factory TombstoneListDto.fromJson(Map<String, dynamic> j) => TombstoneListDto(
        items: (j['items'] as List<dynamic>).map((e) => TombstoneDto.fromJson(e as Map<String, dynamic>)).toList(),
        more: j['more'] as bool,
        next: j['next'] as String,
      );

  Map<String, dynamic> toJson() => {
        'items': items.map((e) => e.toJson()).toList(),
        'more': more,
        'next': next,
      };
}

